const releaseMachinePoolCredentialIfIdle = `-- name: ReleaseMachinePoolCredentialIfIdle :exec
UPDATE machine_pools pool
SET provider_auth_secret_id = NULL,
    updated_at = statement_timestamp()
WHERE pool.org_id = $1
  AND pool.id = $2
  AND pool.deleted_at IS NOT NULL
  AND pool.provider_auth_secret_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM machines machine
    WHERE machine.org_id = pool.org_id
      AND machine.machine_pool_id = pool.id
      AND machine.deleted_at IS NULL
  )
`

type ReleaseMachinePoolCredentialIfIdleParams struct {
	OrgID         uuid.UUID
	MachinePoolID uuid.UUID
}

// A deleted pool keeps its provider credential until every pooled machine has
// finished provider teardown; once idle the credential is released so the
// secret can be deleted.
func (q *Queries) ReleaseMachinePoolCredentialIfIdle(ctx context.Context, arg ReleaseMachinePoolCredentialIfIdleParams) error {
	_, err := q.db.Exec(ctx, releaseMachinePoolCredentialIfIdle, arg.OrgID, arg.MachinePoolID)
	return err
}

